arReg_data[40] := WORD_TO_INT(DWORD_TO_WORD(dwAxisErrorY));
arReg_data[41] := WORD_TO_INT(DWORD_TO_WORD(SHR(dwAxisErrorY, 16)));

// arReg_data[51..52] 保存 Y 轴 MC_ReadStatus.ErrorID。
arReg_data[51] := WORD_TO_INT(DWORD_TO_WORD(TO_DWORD(eStatusErrorY)));
arReg_data[52] := WORD_TO_INT(DWORD_TO_WORD(SHR(TO_DWORD(eStatusErrorY), 16)));

// arReg_data[61..62] 保存 Y 轴 MC_ReadAxisError.ErrorID。
arReg_data[61] := WORD_TO_INT(DWORD_TO_WORD(TO_DWORD(eAxisReadErrorY)));
arReg_data[62] := WORD_TO_INT(DWORD_TO_WORD(SHR(TO_DWORD(eAxisReadErrorY), 16)));

