fbStatusC(
    Axis := AXIS_C,
    Enable := TRUE,
    Valid => ,
    Busy => ,
    Error => bStatusErrorC,
    ErrorID => eStatusErrorC,
    Disabled => ,
    Errorstop => ,
    Stopping => ,
    StandStill => ,
    DiscreteMotion => ,
